int server_bind(struct server *servr, int port, int auto_assign)
{
	servr->serv_addr = malloc(sizeof(struct sockaddr_in));
	if (servr->serv_addr) {
		memset((*servr)->serv_addr->sin_zero, 0, sizeof((*servr)->serv_addr->sin_zero));
	} else {
		return -1;
	}

	servr->timeout = TIMEOUT_DEFAULT;
	servr->backlog = max_connections;
	servr->sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
	servr->serv_addr->sin_family = AF_INET;
	servr->serv_addr->sin_addr.s_addr = INADDR_ANY;

	sem_init(&(servr->connection_sem), 0, 1);
	generic_queue_init(&(servr->connections));

	sem_init(&(servr->message_sem), 0, 1);
	generic_queue_init(&(servr->messages));

	servr->serv_addr->sin_port = htons(port);
	socklen_t size = sizeof(*(servr->serv_addr));
	struct sockaddr_in *addr = servr->serv_addr;

	if (auto_assign == 0) {
		while (bind(servr->sockfd, (struct sockaddr *)addr, size) < 0) {
			servr->serv_addr->sin_port = htons(port++);
		}
	} else if (bind(servr->sockfd, (struct sockaddr *)addr, size) < 0){
		return -1;
	}

	return listen(servr->sockfd, servr->backlog);
}

int server_unbind(struct server *servr)
{
	if (generic_queue_size(servr->messages) > 0) {
		sem_wait(&servr->message_sem);
		generic_queue_destroy(servr->messages, server_message_free);
		sem_post(&servr->message_sem);	
	}
	sem_destroy(&servr->message_sem);

	if (generic_queue_size(servr->open_connections) > 0) {
		sem_wait(&servr->connection_sem);
		generic_queue_destroy(servr->connections, server_connection_free);
		sem_post(&servr->connection_sem);	
	}
	sem_destroy(&servr->connection_sem);

	free(servr->serv_addr);

	return close(servr->sockfd);
}

